    "rus-mongol-invasion-1237-1240": { a: ["1237-1240年；蒙古西征", "50.45N, 30.52E", "梁赞、弗拉基米尔、基辅与罗斯诸公国", "伏尔加河、森林草原和欧亚骑兵通道"], c: "蒙古征服重组罗斯诸公国的贡赋和王公关系，但地方社会与城市网络没有完全消失；金帐汗国框架是后续莫斯科上升的重要环境。", f: ["1237年蒙古军进攻梁赞。", "1238年弗拉基米尔等东北罗斯中心被攻占。", "1240年基辅失陷。", "罗斯王公需向金帐汗国取得统治确认并缴纳贡赋。", "东北罗斯诸公国在征收贡赋和王公竞争中逐渐积累资源。"], d: "[争议] 各地破坏程度不同，不能用单一的“蒙古枷锁”解释数世纪发展。" },
    "rus-peter-great-reforms-1682-1725": { a: ["1682-1725年；彼得一世时期", "59.93N, 30.33E", "莫斯科、圣彼得堡与波罗的海地区", "涅瓦河、波罗的海港口和军工交通线"], c: "彼得改革把军队、财政、官僚与精英教育嵌入欧洲大国竞争，扩大国家动员能力，也以征税、徭役和社会控制为代价。", f: ["1682年彼得一世即位，后逐步取得实权。", "1700至1721年大北方战争推动军队、税制和工业改革。", "1703年圣彼得堡在涅瓦河口开建。", "1721年尼斯塔德和约确认俄国取得波罗的海沿岸重要地区。", "改革强化帝国官僚军政体系，也加重农民和城镇社会的负担。"], d: "[争议] “西化”不能掩盖本土制度延续和改革的强制性成本。" },
    "rus-october-revolution-1917": { a: ["1917年10月；俄国革命", "59.93N, 30.33E", "彼得格勒、莫斯科与俄国帝国", "铁路、战时补给线、城市粮食市场和前线军路"], c: "十月革命发生在二月革命后双重政权、战争、土地和粮食危机中；布尔什维克夺权只是随后内战和国家重建的开端。", f: ["1917年二月革命后临时政府与苏维埃并存。", "临时政府继续参战并无法解决土地和粮食危机。", "10月布尔什维克在彼得格勒控制关键机构。", "革命后新政权与反对力量进入内战。", "苏维埃政权的存续依赖军队、粮食征集和国家机构重建。"], d: "[争议] 革命既包含群众动员也包含组织化夺权，不能以单一模式概括。" },
    "rus-soviet-dissolution-1991": { a: ["1991年；苏联解体", "55.75N, 37.62E", "莫斯科与苏联加盟共和国", "能源网络、联盟行政系统和东西欧交通线"], c: "苏联解体由经济停滞、改革失控、民族政治与中央权威衰落交互造成；外部冷战压力是环境因素而非唯一解释。", f: ["1985年戈尔巴乔夫推行改革和公开性政策。", "改革暴露供应、财政和政治控制的长期问题。", "加盟共和国的主权诉求持续增强。", "1991年8月政变失败削弱联盟中央权威。", "1991年12月苏联解体，俄罗斯联邦与其他独立国家出现。"], d: "[争议] 解体原因不能只归为经济、民族或个人决策，三者相互作用是核心。" }
